<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\User;
use Illuminate\Auth\Access\HandlesAuthorization;

/**
 * Generated by Filament Shield, then extended with account-protection rules:
 *  - Only a super admin can view/update/delete a super admin account.
 *  - Nobody can delete themselves (also enforced for super admins in AppServiceProvider).
 *
 * Re-run Shield with --ignore-existing-policies so these rules are not overwritten.
 */
class UserPolicy
{
    use HandlesAuthorization;

    /** Non-super admins may never touch super admin accounts. */
    private function canManage(User $user, User $model): bool
    {
        return $user->isSuperAdmin() || ! $model->isSuperAdmin();
    }

    public function viewAny(User $user): bool
    {
        return $user->can('view_any_user');
    }

    public function view(User $user, User $model): bool
    {
        return $user->can('view_user') && $this->canManage($user, $model);
    }

    public function create(User $user): bool
    {
        return $user->can('create_user');
    }

    public function update(User $user, User $model): bool
    {
        return $user->can('update_user') && $this->canManage($user, $model);
    }

    public function delete(User $user, User $model): bool
    {
        return $user->can('delete_user')
            && $this->canManage($user, $model)
            && $user->isNot($model);
    }

    public function deleteAny(User $user): bool
    {
        return $user->can('delete_any_user');
    }

    public function forceDelete(User $user, User $model): bool
    {
        return $user->can('force_delete_user')
            && $this->canManage($user, $model)
            && $user->isNot($model);
    }

    public function forceDeleteAny(User $user): bool
    {
        return $user->can('force_delete_any_user');
    }

    public function restore(User $user, User $model): bool
    {
        return $user->can('restore_user') && $this->canManage($user, $model);
    }

    public function restoreAny(User $user): bool
    {
        return $user->can('restore_any_user');
    }

    public function replicate(User $user, User $model): bool
    {
        return $user->can('replicate_user') && $this->canManage($user, $model);
    }

    public function reorder(User $user): bool
    {
        return $user->can('reorder_user');
    }
}
